"""Publish the four visual judgments and export the recommended vector artwork."""
from pathlib import Path
import json,html,shutil,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parent
items=json.loads((ROOT/'all-logos.json').read_text());by_id={i['id']:i for i in items}
selection=json.loads((ROOT/'selection.json').read_text());reviews=[json.loads(p.read_text())for p in sorted((ROOT/'reviews').glob('judge-*.json'))]
winner=by_id[selection['winner']]; export=ROOT/'recommended';export.mkdir(exist_ok=True)
for id,name in [(winner['id'],'eyesight-mark.svg'),('12b','eyesight-alternative-12b.svg')]:
    shutil.copy2(ROOT/by_id[id]['file'],export/name)
svg=(ROOT/winner['file']).read_text();(export/'eyesight-blue.svg').write_text(svg.replace('<svg ','<svg color="#006fe6" ',1))
inner=svg.replace('<svg ','<svg x="29.6" y="66.5" color="white" ',1).replace('width="160" height="100"','width="196.8" height="123"')
(export/'eyesight-app-icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256"><rect width="256" height="256" rx="56.32" fill="#006fe6"/>'+inner+'</svg>\n')
assert (ROOT/'assets/reference.jpg').is_file()
paragraphs=['# Eyesight logo study', 'The study contains fifteen initial eye concepts and two refinements of every concept, for forty five distinct SVG files. Six designers using gpt-6-luna at max reasoning developed the thirty refinements. Four independent judges using the same model and reasoning level inspected every candidate in six actual WebKit screenshot sheets across light and dark themes. Each judge also inspected the supplied reference. They did not receive the other judges’ verdicts or the designers’ preferences.', 'The recommended mark is 01b, Full aperture. It ranked first, second, second and third across the four complete rankings, giving it the strongest equal weight mean position of 2.0. Its fuller almond and larger eight circle iris remain clear beside Comfortaa and retain more structure in the small samples. The closest alternative is 12b, Eight circle iris. It received two first place votes and a mean position of 2.75. It offers a quieter, finer contour. Judge 3 selected the original 01. This is a close visual choice between variations of a coherent eye family, not a unanimous vote.', 'Selection uses the mean position across all four complete rankings, with equal weight for every judge. Lower is stronger. First choice votes break an equal mean, followed by the candidate ID. Every raw ranking and the complete aggregate remain in reviews/ and selection.json. review-snapshot.json records the hashes of the exact SVGs and screenshots assessed. aggregate-reviews.py validates the evidence before recomputing the recommendation.', 'The fixed blue icon field keeps background color and platform corner treatment constant. The concepts vary the eye’s own rounding, aperture, weight, topology, iris construction and overall logic. Each contact card also shows the actual Comfortaa wordmark and monochrome samples at 24, 20 and 16 CSS pixels. Screenshots use the local WebKit renderer at the host backing scale. They are not captures of a real macOS menu bar.', 'Open index.html for the interactive gallery, light and dark appearance controls, family filters, individual analyses and SVG downloads. The concepts and refinements folders contain every original vector. recommended/ contains the leading transparent mark, a blue mark, a blue app tile and the nearest alternative. The Comfortaa font and unmodified SIL license are bundled in assets/. The SVG marks contain no text and need no installed font; the gallery wordmark uses the bundled font.']
for base in json.loads((ROOT/'concepts.json').read_text()):
    variants=[by_id[base['id']+'a'],by_id[base['id']+'b']]
    paragraphs.append(base['id']+' '+base['name']+'. '+base['logic']+' '+base['caution'])
    for v in variants:paragraphs.append(v['id']+' '+v['name']+'. '+v['rationale']+' '+v['tradeoff'])
paragraphs.append('The recommendation is a set of subjective model visual judgments. It does not establish human preference or physical device legibility. The recommended mark has not replaced the installed app identity. No application branding is changed by this study.')
(ROOT/'README.md').write_text('\n\n'.join(paragraphs)+'\n')
team={'initialConcepts':'Authored by the parent agent','designers':[{'task':f'logo_designer_{i}','model':'gpt-6-luna','reasoningEffort':'max','metadata':f'refinements/designer-{i}.json'}for i in range(1,7)],'judges':[{'task':f'logo_vision_judge_{i}','model':'gpt-6-luna','reasoningEffort':'max','review':f'reviews/judge-{i}.json'}for i in range(1,5)]}
(ROOT/'team.json').write_text(json.dumps(team,indent=2)+'\n')
# This presentation shows the frozen winning artwork without changing reviewed sheets.
hero='''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Eyesight recommendation</title><link rel="stylesheet" href="study.css"><style>body{width:1120px;padding:40px;height:640px}header{height:52px}main{display:flex;align-items:center;gap:55px;height:410px}.hero-icon{width:270px;height:270px}.hero-icon svg{width:77%;height:auto}.hero-lockup{font-size:58px;letter-spacing:-2px;margin-bottom:26px;gap:14px}.hero-lockup svg{width:84px;height:62px}.hero-sizes{gap:26px;margin:24px 0}.hero-copy{font-size:17px;max-width:610px}.hero-copy p+p{margin-top:12px}footer{display:flex;align-items:center;gap:15px;border-top:1px solid #7773;padding-top:20px}.alternate{width:84px;height:54px}.alternate svg{width:100%;height:100%}</style></head><body class="dark"><header><div><h1>01b Full aperture</h1><p>Recommended across four Luna 6 Max visual rankings</p></div><span class="muted">15 concepts. 45 candidates.</span></header><main><div class="app-icon hero-icon">WINNER</div><section><div class="wordmark hero-lockup">WINNER<span>eyesight</span></div><div class="hero-copy"><p>A fuller almond. Eight company circles. One calm pupil.</p><p class="muted">Top three with every judge. Mean rank 2.0 across 45 candidates.</p></div><div class="sizes hero-sizes">SIZES</div></section></main><footer><div class="alternate">ALTERNATE</div><p>12b Eight circle iris received two first place votes.<br><span class="muted">A finer, quieter alternative with a mean rank of 2.75.</span></p></footer></body></html>'''
hero=hero.replace('WINNER',svg).replace('ALTERNATE',(ROOT/by_id['12b']['file']).read_text()).replace('SIZES',''.join(f'<span class="size" style="--size:{s}px">{svg}<small>{s}</small></span>'for s in [24,20,16]))
(ROOT/'recommendation.html').write_text(hero)
print('Study complete:',winner['id'],winner['name'])
